import boto3
from urllib.parse import urlparse

if not isinstance(output_dir, Dir):
    raise ValueError("The provided output_dir isn't a Dir Object.")

if output_dir.url is None:
    return

obj = urlparse(output_dir.url)
if obj.scheme != "s3":
    raise ValueError(f"The provided folder should start with s3://. Found {output_dir.path}.")

s3 = boto3.client("s3")
prefix = obj.path.lstrip("/").rstrip("/") + "/"

try:
    s3.head_object(Bucket=obj.netloc, Key=f"{prefix}index.json")
    has_index_file = True
except Exception as e:
    has_index_file = False

if not has_index_file:
    objects = s3.list_objects_v2(Bucket=obj.netloc, Prefix=prefix)
    for obj in objects.get("Contents", []):
        s3.delete_object(Bucket=obj.netloc, Key=obj["Key"])

